DELETE FROM corpus WHERE id = 1;
INSERT INTO corpus (id, source_note, entities, indicators, trends, sections) VALUES (
  1,
  'Editions transcribed from the published clean PDFs supplied by Rubiey suhaimi on 15 Sept 2026: ''Maida Vale-Weekly-Brief-20260904 [Clean].pdf'' and ''Maida_Vale_Weekly_Brief_20260911 [Clean].pdf''. These are the editions of record.',
  '[{"id": "ptp", "name": "Port of Tanjung Pelepas", "group": "MMC Ports"}, {"id": "johor_port", "name": "Johor Port", "group": "MMC Ports"}, {"id": "northport", "name": "Northport", "group": "MMC Ports"}, {"id": "penang_port", "name": "Penang Port", "group": "MMC Ports"}, {"id": "mmc_eng", "name": "MMC Engineering", "group": "MMC"}, {"id": "mmc_land", "name": "MMC Land", "group": "Property"}, {"id": "tbip", "name": "Tanjung Bin Industrial Park", "group": "Property"}, {"id": "sac", "name": "Senai Airport City", "group": "Property"}, {"id": "glenmarie", "name": "Glenmarie Properties", "group": "Property"}, {"id": "proton", "name": "Proton", "group": "Automotive"}, {"id": "perodua", "name": "Perodua", "group": "Automotive"}, {"id": "drb_hicom", "name": "DRB-HICOM", "group": "Automotive"}, {"id": "tradewinds", "name": "Tradewinds Plantation", "group": "Agribusiness"}, {"id": "bernas", "name": "Bernas", "group": "Agribusiness"}, {"id": "malakoff", "name": "Malakoff", "group": "Energy"}, {"id": "gas_malaysia", "name": "Gas Malaysia", "group": "Energy"}, {"id": "petronas", "name": "PETRONAS", "group": "Energy"}, {"id": "bank_muamalat", "name": "Bank Muamalat", "group": "Financial Services"}, {"id": "pos_malaysia", "name": "Pos Malaysia", "group": "Logistics"}, {"id": "kontena", "name": "Kontena Nasional", "group": "Logistics"}, {"id": "pos_aviation", "name": "Pos Aviation", "group": "Aviation"}]',
  '[{"id": "brent", "label": "Brent Crude", "unit": "USD/bbl", "direction_bad": "up", "series": [{"date": "2026-08-28", "value": 89.31}, {"date": "2026-09-04", "value": 96.28}, {"date": "2026-09-11", "value": 104.35}], "note": "Published Pulse values. 4 Sept +7.80% wow; 11 Sept +8.38% wow. Strait of Hormuz traffic impaired."}, {"id": "usdmyr", "label": "USD/MYR", "unit": "", "direction_bad": "up", "series": [{"date": "2026-08-28", "value": 4.0275}, {"date": "2026-09-04", "value": 4.0455}, {"date": "2026-09-11", "value": 4.0685}], "note": "Ringgit weaker as the value rises. Feeds DRB-HICOM imported-component costs."}, {"id": "cnymyr", "label": "CNY/MYR", "unit": "", "direction_bad": "up", "series": [{"date": "2026-08-28", "value": 0.5992}, {"date": "2026-09-04", "value": 0.6028}, {"date": "2026-09-11", "value": 0.6064}], "note": "Yuan-denominated machinery and component costs for DRB-HICOM and data-centre projects."}, {"id": "mgs10", "label": "10-Year MGS Yield", "unit": "%", "direction_bad": "up", "series": [{"date": "2026-09-04", "value": 3.98}, {"date": "2026-09-11", "value": 4.14}], "note": "Up 16 basis points. Raises Bank Muamalat funding costs and pressures sukuk and treasury valuations."}, {"id": "diesel", "label": "Peninsular diesel (unsubsidised)", "unit": "RM/litre", "direction_bad": "up", "series": [{"date": "2026-08-27", "value": 4.72}, {"date": "2026-09-03", "value": 4.67}, {"date": "2026-09-10", "value": 4.92}], "note": "Fell 5 sen, then rose 25 sen for the 10-16 Sept window. BUDI95 subsidised RON95 stays at RM 1.99/litre within the 300-litre monthly cap."}, {"id": "klci", "label": "FBM KLCI", "unit": "pts", "direction_bad": "down", "series": [{"date": "2026-08-28", "value": 1725.88}, {"date": "2026-09-04", "value": 1708.1}, {"date": "2026-09-11", "value": 1686.74}], "note": "Gave up the 1,700 level. No AlBukhary business marks to the index."}, {"id": "foreign_flow", "label": "Net Foreign Flow (weekly outflow)", "unit": "RM mn", "direction_bad": "up", "series": [{"date": "2026-08-21", "value": 549.1}, {"date": "2026-08-28", "value": 366.0}, {"date": "2026-09-04", "value": 640.3}], "note": "Outflow narrowed then widened to RM 640.3 mn. Local institutions recorded RM 120.3 mn of net buying."}, {"id": "palm_stocks", "label": "Palm oil closing stocks", "unit": "mn tonnes", "direction_bad": "up", "series": [{"date": "2026-07-31", "value": 2.62}, {"date": "2026-08-31", "value": 2.82}], "note": "Up 7.48%. Output reached 1.81 mn tonnes; exports fell to 1.29 mn tonnes."}]',
  '[{"title": "Brent has risen for three consecutive weeks, and the recovery horizon moved out a year", "detail": "The published Pulse shows Brent USD 89.31 to USD 96.28 (+7.80% wow) to USD 104.35 (+8.38% wow). The change in the 11 Sept edition is not the level but the horizon: the IEA now expects normal Middle East flows only in 2027, against a previous 2026 assumption. Malakoff''s fuel exposure therefore stops being a spike to absorb and becomes a cost base to plan against, and the 11 Sept Pulse adds Gas Malaysia''s reference-price pass-through lag as a separate named channel, which the 4 Sept Pulse did not isolate.", "entities": ["malakoff", "gas_malaysia"], "indicator": "brent"}, {"title": "Bank Muamalat''s funding pressure widened from one channel to four", "detail": "On 4 Sept the read was a stable funding backdrop with a narrowing lending spread of 2.36% and deposit growth slowing to 5.6%. By 11 Sept four channels are live at once: the 10-year MGS yield rose 16 basis points to 4.14%, the ECB lifted its deposit rate to 2.50% with more signalled, net foreign outflow widened to RM 640.3 mn, and research houses expect higher second-half credit costs. The FOMC on 15-16 Sept and the ECB increase taking effect on 16 Sept land in the same week.", "entities": ["bank_muamalat"], "indicator": "mgs10"}, {"title": "Fleet fuel costs reversed from a tailwind to a headwind in one week", "detail": "The 4 Sept Pulse graded unsubsidised fuel Positive on a 5 sen cut, naming Pos Malaysia, Kontena Nasional and Tradewinds Plantation. The 11 Sept Pulse grades the same row Negative on a 25 sen increase, with Peninsular diesel moving RM 4.67 to RM 4.92. This is the only Pulse row to flip grade between the two editions. BUDI95 held at RM 1.99 throughout, so the exposure is fleet and haulage, not consumer.", "entities": ["pos_malaysia", "kontena", "tradewinds"], "indicator": "diesel"}, {"title": "MMC Ports'' demand signals strengthened while no throughput gain was confirmed", "detail": "Across both editions the demand evidence accumulated: China''s Aug exports rose 25.0%, Malaysia''s Jan-Jul trade rose 24.7% to RM 2.16 tn with exports up 29.2%, manufacturing sales reached RM 177.3 bn, and typhoon disruption at Chinese ports delayed 4.3 mn TEU with Westports cutting yard density to 80%. Both editions are careful that none of this is booked volume. Against that, the 4 Sept edition carries the Penang ferry collision as a liability and safety-directive exposure.", "entities": ["ptp", "johor_port", "northport", "penang_port"], "indicator": null}, {"title": "Malakoff''s story shifted from cost victim to capacity beneficiary", "detail": "The 4 Sept edition frames Malakoff almost entirely through fuel cost and valuation multiples. The 11 Sept edition adds three forward-looking references: a 9 GW gas-fired capacity requirement by 2032 with no new capacity due in 2026-2027, BIMB Research projecting 10.6% sector core earnings growth with higher Tanjung Bin availability and a possible dividend resumption, and Wood Mackenzie''s regional LNG demand lead. The cost pressure is unchanged; what is new is that scarce dependable capacity is now an asset.", "entities": ["malakoff", "gas_malaysia"], "indicator": null}, {"title": "The data-centre theme moved from demand projection into execution, without a Group award", "detail": "The 4 Sept edition notes Singapore awarding only 200 MW, supporting the case for Johor demand. By 11 Sept the theme is concrete: data centres reached 9.3% of Malaysian electricity use against a 7% average, Firmus signed a multi-year OpenAI agreement for two Malaysian sites, and Pekat and TRC secured RM 207.16 mn of data-centre works. Every item is explicit that no AlBukhary company holds an award, so the read stays a tenant-quality and tender-margin reference for TBIP, SAC and MMC Engineering.", "entities": ["tbip", "sac", "mmc_eng", "gas_malaysia"], "indicator": null}, {"title": "Proton''s momentum is intact but the competitive and cost backdrop changed", "detail": "On 4 Sept Proton posted record monthly domestic sales of 22,632 units, 27.9% Aug share, 40.2% year-to-date growth and its best exports since 2011. By 11 Sept the read is more contingent: sub-RM 60,000 S70 variants broaden the range specifically because higher fuel costs test demand, motor-vehicle sales growth of 7.9% feeds the order book, and BYD dropped its Tanjung Malim plant while advancing local assembly talks, keeping contract-manufacturing competition active.", "entities": ["proton", "drb_hicom"], "indicator": null}]',
  '["Global - 1. Macroeconomics and Global Market", "Asia Pacific - 1. Macroeconomics and Regional Market", "Malaysia - 3. Macroeconomics and Local Market", "Malaysia - 4. Ports/Logistics/Infrastructure Sector", "Malaysia - 5. Automotive/Services Sector", "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "Malaysia - 7. Energy/Utilities/Sustainability Sector", "Malaysia - 8. Digital Economy/Technology/Media Sector", "Malaysia - 9. Property Sector", "Malaysia - 10. Aviation Sector", "Malaysia - 11. Financial Services Sector"]'
);

DELETE FROM editions WHERE id = 'W36';
INSERT INTO editions (id, label, date, status, exec_summary, speed_read, structural, pulse, items, watchlist, beyond, pdf) VALUES (
  'W36',
  '31 Aug 2026 to 4 Sept 2026',
  '2026-09-04',
  'Published (clean).',
  'United States (US) forces struck Islamic Revolutionary Guard Corps (IRGC) sites on 1 Sept, including two Iranian government tankers, while Iran retaliated with missiles and drones. Strait of Hormuz traffic remained impaired. Brent settled at USD 96.28 per barrel, up 7.80% week on week (wow) from USD 89.31. Stronger US employment and services data and higher global bond yields added funding pressure. Global air-cargo demand nevertheless rose 3.9% year on year (yoy) in Jul, although Europe-Middle East and Middle East-Asia volumes fell 16.1% and 14.1% respectively. China''s official manufacturing purchasing managers'' index (PMI) rose to 49.8 in Aug from 49.2, while the private measure increased to 51.5 from 50.9. The Association of Southeast Asian Nations (ASEAN) index eased to 52.3 from 52.8. Malaysia-China trade rose 30.6% yoy to USD 80.43 bn in 1H2026 from USD 61.58 bn.

Malaysia''s position remained firm as Bank Negara Malaysia (BNM) held the Overnight Policy Rate (OPR) at 2.75%, although firmer wording raised the risk of a later increase. Proton''s Aug group sales rose 22.7% month on month (mom) to 22,632 units from 18,442, while Perodua''s Jul sales increased 16% mom to 31,842 units ahead of an expected production slowdown. PETRONAS targeted production of 2 mn barrels of oil equivalent per day through 2028, while natural-gas output rose 19.1% yoy to 763.5 bn cubic feet. Baja 3 fertiliser deliveries to Muda Agricultural Development Authority (MADA) farmers restarted on 3 Sept, easing paddy-supply risk for Bernas. The National Farmers Organisation (NAFAS) signed a RM 1.5 bn phosphate-fertiliser memorandum with two Chinese partners offering potential to reduce fertiliser-supply risk for Tradewinds Plantation, although implementation terms were not disclosed.',
  '["US forces struck IRGC sites on 1 Sept, including two Iranian tankers under a new tanker-for-tanker policy; Iran retaliated and Strait traffic stayed impaired.", "US Aug nonfarm payrolls rose 162,000 against 56,000 expected, unemployment held at 4.1% and markets priced about 60% probability of a Sept Federal Reserve increase on CME FedWatch, up from 49%.", "BNM held the OPR at 2.75%, while firmer wording pointed to a possible later increase.", "Proton''s Aug group sales reached 22,632 units, year-to-date sales rose 40.2% to 141,421 units and Aug market share reached 27.9%.", "PETRONAS targeted Malaysian oil and gas production of 2 mn barrels of oil equivalent per day through 2028.", "Baja 3 fertiliser distribution to MADA farmers restarted on 3 Sept and was expected to be completed within 10 days.", "NAFAS signed a five-year phosphate-fertiliser memorandum of understanding with two Chinese partners involving an estimated RM 1.5 bn investment.", "Malaysia''s natural-gas production rose 19.1% yoy to 763.5 bn cubic feet in 2Q2026.", "Singapore awarded only 200 MW of new data-centre capacity, supporting the case for additional Johor demand.", "Malaysian business-loan applications rose 37.7% yoy, but deposit growth slowed to 5.6% and the lending spread narrowed to 2.36%."]',
  'BNM held the OPR at 2.75% with firmer wording, while renewed US-Iran escalation sustained energy and freight pressure. The largest Group exposure remained Malakoff''s fuel cost.',
  '[{"indicator": "Brent Crude", "weekly": "USD 96.28/bbl", "previous": "USD 89.31/bbl", "direction": "↑ 7.80% wow", "implication": "Negative. Higher fuel costs affect Malakoff procurement and MMC Ports customers; monitor contractual pass-through and working capital."}, {"indicator": "USD/MYR", "weekly": "4.0455", "previous": "4.0275", "direction": "↑ 0.45% wow, ringgit weaker", "implication": "Mixed. Bank Muamalat''s funding backdrop remained stable, while imported components became marginally costlier for DRB-HICOM."}, {"indicator": "CNY/MYR", "weekly": "0.6028", "previous": "0.5992", "direction": "↑ 0.60% wow, ringgit weaker", "implication": "Neutral. China-sourced component costs for DRB-HICOM remained broadly predictable."}, {"indicator": "Unsubsidised Fuel Prices per Litre", "weekly": "RON95: RM 3.77; RON97: RM 4.25; Peninsular diesel: RM 4.67", "previous": "RON95: RM 3.82; RON97: RM 4.30; Peninsular diesel: RM 4.72", "direction": "↓ 5 sen each", "implication": "Positive. Lower prices reduce Pos Malaysia, Kontena Nasional and Tradewinds Plantation fleet costs; subsidised BUDI95 RON95 remained RM 1.99/litre."}, {"indicator": "FBM KLCI", "weekly": "1,708.10", "previous": "1,725.88", "direction": "↓ 1.03% wow", "implication": "Neutral. No read-through for Group companies."}, {"indicator": "Net Foreign Flow", "weekly": "RM 366.0 mn outflow, week ended 28 Aug", "previous": "RM 549.1 mn outflow, week ended 21 Aug", "direction": "↑ 33.35% wow, outflow narrowed", "implication": "Positive. Reduced foreign selling supported the ringgit and domestic funding sentiment, although the market remained in net outflow."}]',
  '[{"section": "Global - 1. Macroeconomics and Global Market", "headline": "Global Yields and US Data Raise September Rate-Hike Odds.", "source": "Reuters/The Star/The Edge/BLS, 1-4 Sept 2026", "grade": "Negative", "summary": "The US 10-year Treasury yield touched 4.798% on 1 Sept, Japan''s 10-year yield hit 3% for the first time since 1996 and eurozone inflation rose to 3.3% in Aug from 2.9%. The US Institute for Supply Management (ISM) Services PMI increased to 55.4 from 54.1. Aug nonfarm payrolls rose 162,000 against 56,000 expected, unemployment held at 4.1%.", "impact": "Higher yields compress valuation multiples for Malakoff and Gas Malaysia. A Sept Federal Reserve increase would add pressure to USD/MYR and Bank Muamalat''s US-dollar wholesale-funding costs and sukuk valuations.", "regulatory": "A 25-basis-point European Central Bank increase on 10 Sept is almost fully priced. Markets priced about 60% probability of a Sept Federal Reserve increase on CME FedWatch, up from 49% before the jobs report; the Bank of Japan meets on 17-18 Sept. BNM''s 3 Sept decision to hold the OPR at 2.75% means no immediate domestic policy-rate response.", "entities": ["malakoff", "gas_malaysia", "bank_muamalat"]}, {"section": "Global - 1. Macroeconomics and Global Market", "headline": "Iran Conflict Escalates as US Strikes Tankers and Refiners Diversify Supply.", "source": "Reuters/Axios/The Star, 1-2 Sept 2026", "grade": "Negative", "summary": "US forces struck IRGC sites on 1 Sept, including two government tankers, while Iran retaliated with missiles and drones. Strait of Hormuz traffic remained impaired amid the conflict. Asian refiners increased purchases of Argentine Medanito crude, with Argentina''s exports to Asia averaging a record 35,000 barrels per day through Jul, more than five times the 2025 average.", "impact": "Higher fuel, marine-insurance and freight costs affect Malakoff and MMC Ports customers. Argentine cargoes are too small to offset the Middle East shortfall.", "regulatory": "No ceasefire or Strait reopening agreement was announced. The US tanker-for-tanker response increased the risk to commercial shipping.", "entities": ["malakoff", "ptp", "johor_port"]}, {"section": "Asia Pacific - 1. Macroeconomics and Regional Market", "headline": "China Manufacturing PMI Diverges, with Official Reading at 49.8 and Private Survey at 51.5.", "source": "Reuters, 31 Aug-1 Sept 2026", "grade": "Mixed", "summary": "China''s official National Bureau of Statistics manufacturing PMI rose to 49.8 in Aug from 49.2 in Jul but remained below 50 for a second month. The private RatingDog China General Manufacturing PMI, compiled by S&P Global, increased to 51.5 from 50.9; new export business rose at the fastest pace in six months.", "impact": "Private-sector expansion supports DRB-HICOM component demand and Chinese crude-palm-oil demand that feeds Tradewinds Plantation''s realisations, while the official contraction shows uneven domestic demand. MMC Ports should track whether stronger export orders convert into cargo.", "regulatory": "-", "entities": ["drb_hicom", "tradewinds", "ptp", "johor_port"]}, {"section": "Asia Pacific - 1. Macroeconomics and Regional Market", "headline": "ASEAN Manufacturing PMI Eases to 52.3 in Aug.", "source": "The Star/S&P Global, 3 Sept 2026", "grade": "Mixed", "summary": "The S&P Global ASEAN Manufacturing PMI eased to 52.3 in Aug from 52.8 in Jul, remaining above 50.", "impact": "Regional expansion supports MMC Ports throughput and DRB-HICOM component suppliers, but the 0.5-point easing was a slowdown, not a reversal.", "regulatory": "-", "entities": ["ptp", "johor_port", "drb_hicom"]}, {"section": "Asia Pacific - 1. Macroeconomics and Regional Market", "headline": "Malaysia''s Trade with China, Japan and Indonesia Expands.", "source": "The Edge, 1-3 Sept 2026", "grade": "Positive", "summary": "Malaysia-China trade rose 30.6% yoy to USD 80.43 bn in 1H2026 from USD 61.58 bn, back-calculated from the reported increase, while approved Chinese investment reached USD 3.7 bn. Malaysia-Japan trade increased 11.8% yoy to USD 23.3 bn in Jan-Jul, while Malaysia-Indonesia trade rose 10% yoy to RM 71.1 bn over the same period.", "impact": "Stronger regional trade and investment support industrial supply-chain activity and cargo potential for MMC Ports, while improving market access for DRB-HICOM and Tradewinds Plantation. No import-export split was published, so the throughput read is limited.", "regulatory": "-", "entities": ["ptp", "johor_port", "drb_hicom", "tradewinds"]}, {"section": "Malaysia - 3. Macroeconomics and Local Market", "headline": "BNM Holds OPR at 2.75% with Firmer Policy Wording.", "source": "BNM/The Edge, 3 Sept 2026", "grade": "Mixed", "summary": "BNM''s Monetary Policy Committee held the OPR at 2.75% and adopted firmer wording, omitting ''appropriate'' from its description of the policy stance. BNM expects 2026 growth at the upper end of its 4% to 5% forecast range, while headline and core inflation averaged 1.8% and 2.0% respectively in Jan-Jul. Economists remained divided on the timing of the next rate change.", "impact": "The wording shifts the near-term balance of risk towards a hike rather than a cut. Faster deposit repricing is the principal transmission risk for Bank Muamalat.", "regulatory": "The next scheduled Monetary Policy Committee decision is 5 Nov 2026.", "entities": ["bank_muamalat"]}, {"section": "Malaysia - 3. Macroeconomics and Local Market", "headline": "Malaysia Manufacturing PMI Holds Above 50, but FMM Reports Higher Costs.", "source": "The Star/The Edge, 1-3 Sept 2026", "grade": "Mixed", "summary": "The S&P Global Malaysia Manufacturing PMI remained above 50 for a third month at 50.2 in Aug, down from 50.7 in Jul. The Federation of Malaysian Manufacturing (FMM) Business Conditions Survey showed general business activity falling to 90 in 1H2026 from 103 in 2H2025 and the production-cost index rising to 163 from 146; 96% of manufacturers reported geopolitical disruption.", "impact": "Current PMI expansion supports MMC Ports cargo and Proton supplier activity, but weaker orders, higher input costs and freight disruption threaten 4Q2026 volumes and margins.", "regulatory": "-", "entities": ["ptp", "johor_port", "proton"]}, {"section": "Malaysia - 3. Macroeconomics and Local Market", "headline": "Prime Minister Announces Six Immediate Measures as BUDI Fuel Eligibility Returns to 300 Litres.", "source": "The Edge/The Star/MOF, 1 Sept 2026", "grade": "Positive", "summary": "Measures announced on 30 Aug restored the monthly BUDI95 and BUDI Diesel eligibility limit to 300 litres from 200 litres from 1 Sept; eligible private diesel pick-ups and jeeps can receive up to 400 litres. The package also covered small-business support, school maintenance and expanded digital healthcare.", "impact": "The restored household quota reduces fuel costs and can support consumer spending and Proton demand. Bank Muamalat''s chief economist expected an expansionary Budget 2027 and estimated a fiscal-deficit target near 3.5% of gross domestic product.", "regulatory": "The quota changes took effect on 1 Sept 2026. BUDI95 remains an individual MyKad-based subsidy.", "entities": ["proton", "bank_muamalat"]}, {"section": "Malaysia - 4. Ports/Logistics/Infrastructure Sector", "headline": "Penang Port Ferry-Cargo-Vessel Collision Leaves Services Unaffected.", "source": "Malay Mail/The Edge, 2 Sept 2026", "grade": "Negative", "summary": "Ferry Teluk Bahang collided with cargo vessel MV Mekar Jaya at 8.40 pm on 1 Sept within Penang Port limits. The incident involved 92 people; 21 injuries were reported, 18 people received outpatient treatment and none was admitted. Ferry and port operations continued normally. Penang Port Commission and ferry operator Penang Port Sdn Bhd, an MMC Ports subsidiary, established a task force.", "impact": "An MMC Ports subsidiary operated the ferry and participates in the investigation; the exposure is potential liability and any safety directive, not throughput.", "regulatory": "Penang Port Commission ordered a task-force investigation and a review of operating and safety procedures.", "entities": ["penang_port"]}, {"section": "Malaysia - 4. Ports/Logistics/Infrastructure Sector", "headline": "Penang Manufacturing Investment Rises 38% to RM 17.3 bn in 1H2026.", "source": "The Star, 3 Sept 2026", "grade": "Positive", "summary": "Penang secured RM 17.3 bn of approved manufacturing investment in 1H2026, up 38% yoy and equivalent to 34% of the national total. Foreign investment contributed RM 12.8 bn, or 74% of Penang''s approved manufacturing investment.", "impact": "Approved projects add to prospective container, project-cargo and warehousing demand at Penang Port, subject to implementation, production ramp-up and the import-export mix.", "regulatory": "-", "entities": ["penang_port"]}, {"section": "Malaysia - 5. Automotive/Services Sector", "headline": "Proton Posts Best Overall Monthly Sales Since Jan 2010.", "source": "The Star/The Edge, 3 Sept 2026", "grade": "Positive", "summary": "Proton''s Aug group sales rose 22.7% mom to 22,632 units from 18,442 units in Jul, marking its best overall monthly performance since Jan 2010. Year-to-date sales reached 141,421 units, up 40.2%; Aug market share was 27.9% and year-to-date share was 25.6%. e.MAS 5 deliveries of 4,818 set a national monthly electric-vehicle (EV) record. Exports of 2,477 units were the highest since Jan 2011 and included Geely models assembled under contract at Tanjung Malim.", "impact": "Higher volume and market share lift mobility-segment revenue and utilisation across DRB-HICOM''s 50.1%-owned automotive business, while e.MAS 5 record lifts Proton''s EV position.", "regulatory": "-", "entities": ["proton", "drb_hicom"]}, {"section": "Malaysia - 5. Automotive/Services Sector", "headline": "MBM Resources Flags Slower Perodua Output and Smart Mobility Losses.", "source": "The Star, 3 Sept 2026", "grade": "Mixed", "summary": "MBM Resources and research notes expected Perodua output to moderate during model-line changes and holiday shutdowns. Perodua''s Jul sales rose 16% mom to 31,842 units, while its order backlog fell to 35,000-40,000 units from 60,000 in early 2026. Smart Mobility bookings approached 2,000 in Aug, but production remained below 100 units a month because of supplier-quality issues; MBM remains exposed to Smart Mobility startup losses into 2027.", "impact": "Perodua''s line transition and slow Smart Mobility ramp create a near-term opening for Proton, while higher logistics and parts costs also raise Proton''s input costs.", "regulatory": "-", "entities": ["perodua", "proton"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "Crude Palm Oil Outlook Tightens on Lower Indonesian Output and Record El Nino Risk.", "source": "Bernama/The Edge, 2-3 Sept 2026", "grade": "Mixed", "summary": "The physical crude palm oil (CPO) price for Sept South was RM 4,670 per tonne, while the Nov futures contract closed at RM 4,904 per tonne. The Indonesian Palm Oil Association forecast Indonesia''s 2027 output at 56.8 mn tonnes, down 2.9% from 58.5 mn tonnes in 2026. The World Meteorological Organization said El Nino had a near-100% likelihood of persisting through Feb 2027 with potential to become the strongest recorded.", "impact": "Lower Indonesian supply, B50 biodiesel demand and El Nino support Tradewinds Plantation''s CPO realisations, but fertiliser prices that were 30% higher and weather disruption threaten yields and margins. The relevant read is net contribution after fertiliser cost, not headline price.", "regulatory": "-", "entities": ["tradewinds"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "Indonesia Plans Mandatory Commodity Exchange in 2027 as Bursa CPO Benchmark Retains Advantage.", "source": "Reuters, 3 Sept 2026", "grade": "Mixed", "summary": "Indonesia plans a new exchange for palm oil, nickel, coal and other strategic commodities, with mandatory participation targeted from 2027. Bursa Malaysia Derivatives recorded 19.62 mn CPO futures contracts in 2025, equivalent to 490.43 mn tonnes, versus 30,341 lots and 151,705 tonnes on Indonesia''s palm-oil bourse.", "impact": "Bursa''s liquidity supports Malaysian CPO price discovery and Tradewinds Plantation''s hedging, while Indonesia''s planned mandatory channel introduces uncertainty over export flows, compliance costs and regional basis pricing.", "regulatory": "-", "entities": ["tradewinds"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "NAFAS Signs RM 1.5 bn Fertiliser Memorandum with Chinese Partners.", "source": "The Edge/Bernama, 4 Sept 2026", "grade": "Positive", "summary": "NAFAS signed a five-year memorandum of understanding with Guizhou Phosphate Chemical Group and Jiangsu Chemical Design Institute involving an estimated RM 1.5 bn investment. The proposed collaboration covers phosphate-fertiliser processing, long-term raw-material supply, technology transfer and local technical development.", "impact": "Local phosphate processing offers potential to reduce fertiliser-supply volatility for Tradewinds Plantation and Bernas through lower paddy input cost. No near-term cost benefit until implementation is confirmed.", "regulatory": "-", "entities": ["tradewinds", "bernas"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "Baja 3 Fertiliser Distribution to MADA Farmers Resumes.", "source": "The Star, 3 Sept 2026", "grade": "Positive", "summary": "The government reassigned the remaining Baja 3 fertiliser supply from Taveekun Manufacturing to Malaysian NPK Fertilizer after distribution delays. Deliveries began on 3 Sept and were expected to be completed within 10 days.", "impact": "Restored fertiliser delivery reduces near-term paddy-production disruption in the MADA area and supports domestic rice-supply continuity for Bernas, subject to full and timely delivery.", "regulatory": "MADA was instructed to monitor deliveries, and the previous supplier''s services were terminated.", "entities": ["bernas"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "Serian Haze Emergency Declared as Sarawak Air Quality Deteriorates.", "source": "Reuters/The Edge/Malay Mail, 1-4 Sept 2026", "grade": "Negative", "summary": "The King consented to an emergency in Serian district on 4 Sept after the Air Pollutant Index reached 519, above the 500 emergency threshold. Six Sarawak stations were hazardous on 1 Sept, including Kuching at 407 and Serian at 408, and cloud seeding was conducted. AirAsia warned that some flights might be cancelled, while Malaysia Airlines and Batik Air reported no suspensions.", "impact": "Haze poses operational-disruption risk to Tradewinds Plantation''s Sarawak estates and airline operations, but public disclosures do not place a Tradewinds estate in Serian. Direct exposure to the emergency area is therefore unconfirmed.", "regulatory": "The emergency was confined to Serian district; essential services were to remain operational.", "entities": ["tradewinds"]}, {"section": "Malaysia - 7. Energy/Utilities/Sustainability Sector", "headline": "PETRONAS Targets 2 mn Barrels of Oil Equivalent Per Day and Adds AI Tools to Upstream Data Platform.", "source": "The Star/The Edge/PETRONAS, 2-4 Sept 2026", "grade": "Positive", "summary": "PETRONAS aims to sustain Malaysian oil and gas production at 2 mn barrels of oil equivalent per day through 2028. It spent RM 41.4 bn of capital expenditure in 1H2026, including RM 9 bn, equivalent to 22% of total capital expenditure, on upstream activities; analysts expect upstream investment to recover in 2027. PETRONAS also added agentic AI tools to its myPROdata platform to accelerate upstream evaluation, supporting an ambition to attract RM 50 bn to RM 60 bn of annual upstream investment and halve the discovery-to-first-hydrocarbon period to 50 months.", "impact": "Production visibility supports domestic gas supply for Gas Malaysia, while faster upstream evaluation and a potential 2027 spending recovery support MMC Oil & Gas Engineering''s tender pipeline. No Group award was announced.", "regulatory": "-", "entities": ["petronas", "gas_malaysia", "mmc_eng"]}, {"section": "Malaysia - 7. Energy/Utilities/Sustainability Sector", "headline": "Malaysia''s Natural-Gas Production Rises 19.1% in 2Q2026.", "source": "DOSM/The Edge, 3 Sept 2026", "grade": "Positive", "summary": "Natural-gas production rose 19.1% yoy to 763.5 bn cubic feet in 2Q2026 from 640.9 bn cubic feet. Liquefied natural gas (LNG) exports increased to RM 16.1 bn from RM 12.9 bn in 1Q2026, while imports rose to RM 1.6 bn from RM 1.3 bn.", "impact": "Higher national output improves gas supply for Gas Malaysia and Malakoff, although the domestic benefit depends on allocation to Peninsular Malaysia versus exports.", "regulatory": "-", "entities": ["gas_malaysia", "malakoff"]}, {"section": "Malaysia - 7. Energy/Utilities/Sustainability Sector", "headline": "Shell Explores USD 1 bn Sale of Majority Stake in Bintulu Gas-to-Liquids Venture.", "source": "The Edge, 2 Sept 2026", "grade": "Neutral", "summary": "Shell is exploring the sale of its 72% stake in Shell MDS (Malaysia), the Bintulu gas-to-liquids venture, in a possible USD 1 bn transaction, equivalent to RM 4.05 bn. Discussions are preliminary and no decision has been made.", "impact": "A completed transaction would provide a valuation reference for Malaysian gas assets, but no Group exposure was disclosed.", "regulatory": "-", "entities": ["gas_malaysia", "malakoff"]}, {"section": "Malaysia - 8. Digital Economy/Technology/Media Sector", "headline": "DayOne Considers 1.5 GW On-Site Power Structure with TNB.", "source": "The Star, 3 Sept 2026", "grade": "Positive", "summary": "DayOne is considering a 1.5 GW on-site generation structure with Tenaga Nasional Berhad (TNB) in Selangor. RHB Research''s illustrative scenario assumes 1.5 GW of solar capacity, 50% battery storage, a 70% TNB stake, a 21-year agreement, a 10% internal rate of return and RM 448 mn of earnings; these are analyst assumptions, not confirmed terms.", "impact": "The structure illustrates the pairing of large data-centre loads with generation, storage and long-term supply contracts. Malakoff''s independent-power-producer strategy is the channel, alongside data-centre demand at Tanjung Bin Industrial Park and Senai Airport City.", "regulatory": "On-site generation and Corporate Renewable Energy Supply Scheme supply require Energy Commission, grid and other applicable approvals.", "entities": ["malakoff", "tbip", "sac"]}, {"section": "Malaysia - 8. Digital Economy/Technology/Media Sector", "headline": "Singapore Awards Only 200 MW of New Data-Centre Capacity as Johor Spillover Potential Rises.", "source": "The Star, 2 Sept 2026", "grade": "Positive", "summary": "Singapore provisionally awarded 200 MW of new data-centre capacity. Johor had 1,110 MW of operational information-technology (IT) capacity in 1H2026, 602 MW under construction and 2,486 MW planned; colocation vacancy was 0.7%.", "impact": "Singapore''s constraint supports Johor spillover and land demand at Tanjung Bin Industrial Park and Senai Airport City, subject to power, water and planning availability.", "regulatory": "-", "entities": ["tbip", "sac"]}, {"section": "Malaysia - 8. Digital Economy/Technology/Media Sector", "headline": "Kerjaya Secures RM 858 mn Johor Data-Centre Contract.", "source": "The Edge, 3 Sept 2026", "grade": "Mixed", "summary": "Kerjaya Prospek secured its first data-centre contract, covering mechanical, electrical and plumbing (MEP) fit-out at Iskandar Puteri over eight months. The award lifted its 2026 contract wins to RM 3.2 bn and order book to RM 5.9 bn.", "impact": "The award confirms live MEP demand in Iskandar Puteri, where MMC Engineering competes for packages, but enhances a competitor''s credentials. No Group award was announced.", "regulatory": "-", "entities": ["mmc_eng"]}, {"section": "Malaysia - 9. Property Sector", "headline": "AME Industrial-Property and Construction Activity Expands.", "source": "The Star, 1 Sept 2026", "grade": "Positive", "summary": "In the first quarter of financial year 2027 ended 30 Jun, AME''s revenue rose 4% yoy to RM 196 mn, with construction revenue up 74% and property-investment revenue up 22%. New industrial-property sales were RM 62.1 mn. Separate bookings stood at RM 35.4 mn in Johor, while the Northern TechValley joint venture in Penang had RM 117.2 mn of bookings not yet recognised as revenue.", "impact": "Strong industrial demand in Johor and Penang supports the market backdrop for Glenmarie Properties, DRB-HICOM''s property arm, although AME''s pipeline increases competition for tenants and industrial land.", "regulatory": "-", "entities": ["glenmarie", "drb_hicom"]}, {"section": "Malaysia - 10. Aviation Sector", "headline": "Global Air-Cargo Demand Rises 3.9% in Jul.", "source": "IATA, 31 Aug 2026", "grade": "Mixed", "summary": "The International Air Transport Association (IATA) said global cargo tonne-kilometres rose 3.9% yoy in Jul, including 4.7% growth in international operations. Capacity increased 1.7% overall and 1.8% internationally. PETRONAS Dagangan separately reported that jet-fuel demand had begun to recover, although higher 3Q prices threaten airline margins.", "impact": "Overall cargo growth supports Pos Aviation''s cargo handling and Senai''s logistics activity, but Gulf-linked route contractions and higher jet-fuel costs create pressure on airline capacity and margins.", "regulatory": "-", "entities": ["pos_aviation", "sac"]}, {"section": "Malaysia - 10. Aviation Sector", "headline": "AirAsia Plans Up to USD 1 bn and RM 700 mn Fundraising for Refinancing.", "source": "The Star, 3 Sept 2026", "grade": "Neutral", "summary": "AirAsia said planned funding of up to USD 1 bn in international debt and RM 700 mn in local facilities is mainly for refinancing and balance-sheet consolidation after a USD 300 mn raise in Mar 2026. According to sources, the Ministry of Finance separately appointed an adviser to assess funding needs.", "impact": "Balance-sheet stabilisation supports route continuity, including at Senai, but refinancing and execution risks remain.", "regulatory": "-", "entities": ["sac"]}, {"section": "Malaysia - 10. Aviation Sector", "headline": "Malaysia Aviation Group (MAG) Maintains Fuel Hedging as Jet-Fuel Costs Pressure Operations.", "source": "The Edge, 4 Sept 2026", "grade": "Negative", "summary": "MAG will continue hedging fuel costs in 2027 after cutting 5% of its destinations. Fuel represents an estimated 40% of costs; each USD 1/bbl increase adds an estimated RM 50 mn to annual costs. Malaysia Airlines will resume four weekly Kuala Lumpur-Busan services from 2 Dec.", "impact": "Destination cuts pose downside to Pos Aviation''s handling volumes if its stations are affected, while fuel hedging and the Busan service provide partial offsets. The affected destinations and any exposure at Senai Airport were not disclosed.", "regulatory": "-", "entities": ["pos_aviation", "sac"]}, {"section": "Malaysia - 11. Financial Services Sector", "headline": "Funding Costs Weigh on Malaysian Banks Despite Stronger Business Lending.", "source": "The Star, 3 Sept 2026", "grade": "Mixed", "summary": "Business-loan applications rose 37.7% yoy in Jul and approvals increased 51.9%, lifting the approval rate to 65.2% from 60.8%. Business loans grew 7.5% yoy, but deposit growth slowed to 5.6% and the lending spread narrowed three basis points mom to 2.36%.", "impact": "Stronger business demand expands Bank Muamalat''s financing pipeline, while slower deposit growth and narrower spreads increase funding competition and pressure margins. Asset quality remained stable, with the system gross impaired-loan ratio at 1.43%.", "regulatory": "-", "entities": ["bank_muamalat"]}]',
  '["Strait of Hormuz and Brent. Monitor US-Iran developments, vessel restrictions, marine-insurance premiums and Brent prices for Malakoff''s fuel cost, Gas Malaysia''s lagged reference-price pass-through and MMC Ports customers'' freight cost. OPEC+ meets on 6 Sept on Oct output, expected unchanged.", "Malaysia''s Jul industrial production and manufacturing sales, 9 Sept. Assess output and sales momentum, particularly in export-oriented manufacturing and transport equipment, for MMC Ports throughput and Proton supplier activity.", "European Central Bank policy decision, 9-10 Sept. Monitor the rate decision and inflation guidance for Bank Muamalat''s funding costs, the ringgit and Malakoff and Gas Malaysia valuation multiples.", "Malaysian Palm Oil Board Aug data, 10 Sept. Track production, exports and inventories, with direct implications for Tradewinds Plantation''s cash flow.", "US Aug inflation, 11 Sept. Track headline and core consumer-price inflation for Federal Reserve expectations, USD/MYR and Bank Muamalat''s funding and treasury positions.", "Penang Port investigation. Track task-force findings and any navigation-radar or ferry-safety directives affecting Penang Port operations.", "East Malaysia haze. Monitor the Serian emergency after the Air Pollutant Index reached 519, wider Sarawak readings and confirmed flight cancellations. Haze presents an operational risk to Tradewinds Plantation''s Sarawak estates, although direct exposure in Serian is unconfirmed."]',
  'Federal Open Market Committee, 15-16 Sept; Bank of Japan, 17-18 Sept; Budget 2027 tabling, 9 Oct, including the subsidy-rationalisation timetable for Malakoff and Gas Malaysia; and the Lloyd''s List One Hundred Container Ports 2026 ranking, which will provide the first consolidated Port of Johor ranking for the Port of Tanjung Pelepas and Johor Port.',
  NULL
);

DELETE FROM editions WHERE id = 'W37';
INSERT INTO editions (id, label, date, status, exec_summary, speed_read, structural, pulse, items, watchlist, beyond, pdf) VALUES (
  'W37',
  '7 Sept 2026 to 11 Sept 2026',
  '2026-09-11',
  'Published (clean).',
  'Global cost pressures remained elevated. Brent reached USD 104.35 per barrel on 11 Sept, up 8.38% week on week (wow) from USD 96.28. The International Energy Agency (IEA) projected 2026 oil supply to fall 5.7 mn barrels per day (bpd) and demand 2.5 mn bpd, with normal Gulf flows delayed into 2027. The European Central Bank (ECB) lifted its deposit rate to 2.50% and pointed to further tightening, while US producer inflation reached 5.4% year on year (yoy).

Asia''s trade data remained strong, but oil above USD 100 renewed inflation and subsidy pressure across importing economies. China''s Aug exports rose 25.0% yoy to USD 401.44 bn, imports increased 28.2% to USD 282.35 bn and the surplus widened to USD 119.09 bn. Consumer inflation reached 0.8% yoy from 0.5%, while producer inflation rose to 3.8% from 3.5%. Malaysia and Thailand are expected to lead regional liquefied natural gas (LNG) demand growth as data centres expand and domestic gas output declines.

Malaysia''s domestic data held up across trade, industrial production and consumer spending, leaving external cost pressure rather than demand as the binding constraint. The ringgit stayed broadly stable against the US dollar and yuan, with the modest weekly weakness feeding component procurement at DRB-HICOM rather than threatening the currency position. Equities gave up the 1,700 level on weaker risk appetite. Proton opened bookings at a lower entry point while BYD stepped back from its Tanjung Malim plant, and a Tradewinds director agreed to explore technology cooperation. Higher energy, freight and financing costs remain the main near-term risks.',
  '["The IEA expects 2026 oil supply to fall 5.7 mn bpd and demand to decline 2.5 mn bpd.", "China''s Aug exports rose 25.0% yoy to USD 401.44 bn, while imports increased 28.2%.", "Malaysia''s Jan-Jul trade rose 24.7% yoy to RM 2.16 tn from RM 1.73 tn.", "Tradewinds and SK Telecom agreed to explore cooperation; project scope remains undisclosed.", "BIMB Research projects 2026 utilities core earnings growth of 10.6% yoy, with higher Tanjung Bin availability underpinning Malakoff''s recovery.", "Proton opened bookings for two S70 variants with estimated prices below RM 60,000.", "Gas Malaysia and PETRONAS Gas signed a joint study agreement for a pipeline linking the proposed Yan, Kedah LNG regasification terminal to the Peninsular Gas Utilisation system.", "BYD dropped its Tanjung Malim plant plan but said local assembly discussions were advanced.", "Firmus signed a multi-year OpenAI agreement covering two Malaysian data centres.", "Malaysia''s Aug palm oil stocks rose 7.48% to 2.82 mn tonnes as production stayed firm."]',
  'External cost and financing pressure increased as energy prices and global yields rose, while the ringgit''s modest weakness added procurement pressure for DRB-HICOM. Firm Malaysian trade and manufacturing gave MMC Ports a demand buffer, and margin defence at Malakoff, Gas Malaysia and Pos Malaysia became the near-term priority alongside selective project financing at Bank Muamalat.',
  '[{"indicator": "Brent Crude", "weekly": "USD 104.35/bbl", "previous": "USD 96.28/bbl", "direction": "↑ 8.38% wow", "implication": "Negative. Higher fuel costs affect Malakoff procurement and MMC Ports customers, with a separate reference-price pass-through lag at Gas Malaysia; monitor contractual pass-through and working capital."}, {"indicator": "USD/MYR", "weekly": "4.0685", "previous": "4.0455", "direction": "↑ 0.57% wow, ringgit weaker", "implication": "Mixed. The ringgit stayed broadly stable, while the weaker weekly close raises imported-component costs for DRB-HICOM."}, {"indicator": "CNY/MYR", "weekly": "0.6064", "previous": "0.6028", "direction": "↑ 0.60% wow, ringgit weaker", "implication": "Mixed. The cross-rate held broadly stable, while the weaker weekly close raises yuan-denominated machinery and component costs for DRB-HICOM and data-centre projects."}, {"indicator": "Unsubsidised Fuel Prices per Litre", "weekly": "RON95: RM 4.02; RON97: RM 4.50; Peninsular diesel: RM 4.92", "previous": "RON95: RM 3.77; RON97: RM 4.25; Peninsular diesel: RM 4.67", "direction": "↑ 25 sen each", "implication": "Negative. Higher unsubsidised fuel costs raise Pos Malaysia and MMC Ports haulage expenses; BUDI95 stays at RM 1.99/litre within the 300-litre monthly cap."}, {"indicator": "10-Year MGS Yield", "weekly": "4.14%", "previous": "3.98%", "direction": "↑ 16 basis points", "implication": "Negative. Higher Malaysian Government Securities (MGS) yields raise Bank Muamalat''s funding costs and pressure sukuk and treasury valuations."}, {"indicator": "FBM KLCI", "weekly": "1,686.74", "previous": "1,708.10", "direction": "↓ 1.25% wow", "implication": "Negative. Weaker risk appetite lowers the valuation reference for Malaysian listed holdings; no AlBukhary business marks to the index."}, {"indicator": "Net Foreign Flow", "weekly": "RM 640.3 mn outflow, week ended 4 Sept", "previous": "RM 366.0 mn outflow, week ended 28 Aug", "direction": "↑ RM 274.3 mn outflow widened", "implication": "Negative. Foreign selling weighs on the ringgit and funding sentiment; local institutions recorded RM 120.3 mn of net buying."}]',
  '[{"section": "Global - 1. Macroeconomics and Global Market", "headline": "IEA Cuts 2026 Oil Outlook as Gulf Recovery Slips to 2027.", "source": "Reuters, 11 Sept 2026", "grade": "Negative", "summary": "The IEA forecasts 2026 supply will fall 5.7 mn bpd and demand 2.5 mn bpd, against a previous estimate of a 1.6 mn bpd demand decline. Aug production fell 1.6 mn bpd to 100.1 mn bpd; normal Middle East flows are now expected in 2027.", "impact": "Delayed Gulf recovery sustains Malakoff fuel and MMC Ports freight pressure; the demand fall points to softer cargo activity.", "regulatory": "-", "entities": ["malakoff", "ptp", "johor_port"]}, {"section": "Global - 1. Macroeconomics and Global Market", "headline": "ECB Points to More Rate Increases as US Producer Inflation Accelerates.", "source": "Reuters, 10-11 Sept 2026", "grade": "Negative", "summary": "The ECB raised its deposit rate 25 basis points to 2.50% on 10 Sept. Officials said more increases may be needed, while markets priced at least three over the next year. US Aug producer prices rose 0.4% month on month (mom) and 5.4% yoy; US consumer inflation is due after the Malaysian close.", "impact": "Higher yields raise Bank Muamalat''s US-dollar funding costs and pressure sukuk valuations; US inflation will guide the Federal Reserve decision.", "regulatory": "The ECB rate takes effect on 16 Sept; the Federal Reserve meets on 15-16 Sept.", "entities": ["bank_muamalat"]}, {"section": "Global - 1. Macroeconomics and Global Market", "headline": "European Gas Reaches Three-Year High as Storage Trails Seasonal Norm.", "source": "Bloomberg/The Star, 10 Sept 2026", "grade": "Negative", "summary": "European natural-gas futures rose as much as 5.2% to the highest since Jan 2023 as storage stood at 67% versus a seasonal norm of 83%. Qatar sent its first LNG cargo since Jul through the Strait of Hormuz, but further export visibility was limited.", "impact": "Higher European competition for LNG raises procurement risk for Gas Malaysia and Malakoff if Asian spot supply tightens. Malaysia''s net-exporter position provides a partial offset.", "regulatory": "No Strait reopening or additional Qatari export schedule was announced.", "entities": ["gas_malaysia", "malakoff"]}, {"section": "Asia Pacific - 1. Macroeconomics and Regional Market", "headline": "China''s Exports Rise 25% as Imports Increase 28.2%.", "source": "Reuters, 8 Sept 2026", "grade": "Positive", "summary": "China''s exports rose 25.0% yoy to USD 401.44 bn in Aug, while imports increased 28.2% to USD 282.35 bn. The trade surplus widened to USD 119.09 bn from USD 112.50 bn in Jul.", "impact": "Higher regional trade raises transshipment potential at Port of Tanjung Pelepas (PTP) and Johor Port and demand for DRB-HICOM''s automotive components.", "regulatory": "-", "entities": ["ptp", "johor_port", "drb_hicom"]}, {"section": "Asia Pacific - 1. Macroeconomics and Regional Market", "headline": "China''s Consumer and Producer Inflation Accelerates in Aug.", "source": "Reuters/NBS, 9 Sept 2026", "grade": "Mixed", "summary": "Consumer-price inflation rose to 0.8% yoy in Aug from 0.5% in Jul. Producer-price inflation increased to 3.8% from 3.5%, while core inflation reached 1.0%.", "impact": "Higher producer inflation raises Chinese component-cost risk for DRB-HICOM, while firmer consumer prices indicate improved domestic demand.", "regulatory": "-", "entities": ["drb_hicom"]}, {"section": "Asia Pacific - 1. Macroeconomics and Regional Market", "headline": "Malaysia and Thailand Set to Lead Southeast Asian LNG Demand Growth.", "source": "Wood Mackenzie/The Edge, 7 Sept 2026", "grade": "Neutral", "summary": "Wood Mackenzie expects Malaysia and Thailand to lead regional LNG demand as data-centre capacity expands and domestic gas output declines. Southeast Asian data-centre capacity is projected to rise to 9.4 GW by 2035 from 2.8 GW.", "impact": "The demand projection gives Gas Malaysia a regional volume reference and Malakoff a gas-supply planning reference. Johor''s data-centre concentration also favours land demand at Tanjung Bin Industrial Park (TBIP) and Senai Airport City (SAC); no volume is contracted at this stage.", "regulatory": "-", "entities": ["gas_malaysia", "malakoff", "tbip", "sac"]}, {"section": "Malaysia - 3. Macroeconomics and Local Market", "headline": "Wholesale and Retail Trade Rises 9.0% to RM 170.5 bn.", "source": "DOSM/Bernama, 11 Sept 2026", "grade": "Positive", "summary": "Jul wholesale sales rose 11.7% yoy, retail 6.4% and motor vehicles 7.9%, lifting total sales 9.0% to RM 170.5 bn.", "impact": "Motor-vehicle sales feed Proton''s order book and Bank Muamalat''s hire-purchase financing pipeline; higher fuel prices test follow-through.", "regulatory": "-", "entities": ["proton", "bank_muamalat"]}, {"section": "Malaysia - 3. Macroeconomics and Local Market", "headline": "Malaysia''s Trade Rises 24.7% to RM 2.16 tn in Jan-Jul.", "source": "MATRADE/The Star, 8 Sept 2026", "grade": "Positive", "summary": "Trade rose 24.7% yoy to RM 2.16 tn, on MATRADE''s reported basis. Exports increased 29.2% to RM 1.17 tn and the surplus reached RM 170.50 bn.", "impact": "Export growth raises cargo potential at PTP, Johor Port, Northport and Penang Port, led by electrical and electronics trade.", "regulatory": "-", "entities": ["ptp", "johor_port", "northport", "penang_port"]}, {"section": "Malaysia - 3. Macroeconomics and Local Market", "headline": "Industrial Production Index Growth Eases to 4.7% as Manufacturing Sales Rise 9.1%.", "source": "DOSM/The Star, 9 Sept 2026", "grade": "Mixed", "summary": "Jul Industrial Production Index (IPI) growth eased to 4.7% yoy from 6.5% in Jun. Manufacturing sales rose 9.1% to RM 177.3 bn from RM 162.5 bn.", "impact": "Manufacturing growth lifts throughput at MMC Ports and volumes at Proton, but weaker mining and slower headline growth show uneven momentum.", "regulatory": "-", "entities": ["ptp", "johor_port", "proton"]}, {"section": "Malaysia - 4. Ports/Logistics/Infrastructure Sector", "headline": "Westports Reduces Yard Density After China Port Disruptions.", "source": "UOBKH Research/The Star, 8 Sept 2026", "grade": "Neutral", "summary": "Seven consecutive typhoons at Chinese ports delayed 4.3 mn twenty-foot equivalent units (TEUs) of cargo. Westports reduced yard density to 80% by mid-Aug from 90-95% in late Jul.", "impact": "Diverted China volume reaching Port Klang and Johor raises handling demand at Northport, PTP and Johor Port, while Westports'' density reduction sets the operating reference for congestion response. No throughput gain is confirmed.", "regulatory": "-", "entities": ["northport", "ptp", "johor_port"]}, {"section": "Malaysia - 4. Ports/Logistics/Infrastructure Sector", "headline": "Cyberattack Suspends Container Terminal Operations at Port of Tanjung Pelepas.", "source": "PTP statements/Reuters/The Edge, 10-14 Sept 2026", "grade": "Negative", "summary": "PTP detected a cyber incident at 23:34 on 9 Sept and suspended container terminal operations. A phased restart began on 10 Sept and PTP was still cleaning up affected systems as at 14 Sept. PTP has not confirmed the cause, whether ransomware was involved, whether data was lost, or any financial impact.", "impact": "PTP is the largest asset in MMC Ports. Suspended container operations mean lost handling days that cannot be recovered within the quarter, plus vessel-bunching and yard congestion costs through the restart. Transshipment customers can divert to Singapore at short notice, so the exposure extends past the outage to volume that does not return. Treat the throughput and revenue effect as unquantified until PTP reports.", "regulatory": "No regulator has announced an inquiry. NACSA notification obligations for critical national information infrastructure would apply; PTP has not commented on them.", "entities": ["ptp"], "flag": "Filed late. This item falls inside the 5-11 Sept window and was absent from the edition filed on 11 Sept — added on 15 Sept. Cause, ransomware, data loss and financial impact remain unconfirmed by PTP and must not be asserted."}, {"section": "Malaysia - 5. Automotive/Services Sector", "headline": "Proton Opens Bookings for Estimated Sub-RM 60,000 S70 Variants.", "source": "The Star, 7 Sept 2026", "grade": "Positive", "summary": "Bookings opened for S70 Lite and Prime with a 1.5-litre naturally aspirated engine and continuously variable transmission. Final prices are pending; average monthly S70 sales exceeded 2,500 units in 2026.", "impact": "The lower entry point broadens Proton''s sedan range as higher fuel costs test demand; final pricing and sales mix determine the margin effect.", "regulatory": "-", "entities": ["proton"]}, {"section": "Malaysia - 5. Automotive/Services Sector", "headline": "BYD Drops Tanjung Malim Plant Plan but Advances Local Assembly Talks.", "source": "The Star, 11 Sept 2026", "grade": "Mixed", "summary": "BYD cancelled its Tanjung Malim plant but said Malaysian vendor and assembly talks are advanced. Indonesian imports remain a contingency for supply or demand gaps.", "impact": "The cancellation delays BYD''s build-out near Proton City, but assembly talks keep contract-manufacturing competition active.", "regulatory": "-", "entities": ["proton", "drb_hicom"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "Palm Oil Output Set to Stay Firm as Aug Stocks Rise 7.48%.", "source": "MPOB/BIMB Research/The Star, 9-10 Sept 2026", "grade": "Mixed", "summary": "Malaysian Palm Oil Board (MPOB) data showed Aug stocks rose 7.48% to 2.82 mn tonnes from 2.62 mn tonnes as output reached 1.81 mn tonnes and exports fell to 1.29 mn tonnes. BIMB Research expects seasonally firm production over the next two to three months.", "impact": "Higher output lifts Tradewinds Plantation volumes, while rising stocks limit price upside. Fertiliser and logistics costs remain earnings risks.", "regulatory": "-", "entities": ["tradewinds"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "East Coast Poised to Become Food-Security Hub.", "source": "MIDA/The Star, 8 Sept 2026", "grade": "Neutral", "summary": "The Malaysian Investment Development Authority (MIDA) identified smart farming, food processing, cold chains and East Coast Rail Link connectivity as growth opportunities. Across all sectors, the region recorded RM 61.4 bn in approved investment from 2021 to Jun 2026.", "impact": "Food-processing and cold-chain projects widen Bank Muamalat''s financing prospects and raise East Coast logistics demand over the investment horizon; rail connectivity increases gateway competition for MMC Ports. No allocation or award has been made.", "regulatory": "The New Incentive Framework prioritises high-impact and sustainable investment; no new food-security allocation was announced.", "entities": ["bank_muamalat", "ptp", "johor_port"]}, {"section": "Malaysia - 6. Agribusiness/Plantation/Food Security Sector", "headline": "Serian Haze Emergency Lifted as Air Quality Improves.", "source": "Reuters, 7 Sept 2026", "grade": "Neutral", "summary": "The emergency declaration in Serian district, Sarawak was lifted on 7 Sept after the Air Pollutant Index fell below the emergency threshold of 500, from a peak of 519 on 4 Sept. Authorities cautioned that readings in Serian and Samarahan remained poor.", "impact": "Easing air quality removes the near-term operational-disruption risk to Tradewinds Plantation''s Sarawak estates previously flagged; public disclosures still place no Tradewinds estate inside the Serian district.", "regulatory": "Emergency declaration lifted on 7 Sept; air-quality monitoring continues.", "entities": ["tradewinds"]}, {"section": "Malaysia - 7. Energy/Utilities/Sustainability Sector", "headline": "Data Centres Lift Electricity Share to 9.3% as Malaysia Needs 9 GW of Gas Capacity by 2032.", "source": "Reuters, 8 Sept 2026", "grade": "Neutral", "summary": "Data centres'' share of electricity use reached a record 9.3% in the second week of Aug from a 7% average in 2026. Their share is projected to reach 31% by 2035. Malaysia needs 9 GW of added gas-fired capacity by 2032, with no new gas capacity due in 2026-2027.", "impact": "The 9 GW requirement gives Malakoff a capacity-planning reference and Gas Malaysia a gas-demand reference through 2032. No project award or investment decision was announced.", "regulatory": "Coal retirement is targeted for 2044.", "entities": ["malakoff", "gas_malaysia"]}, {"section": "Malaysia - 7. Energy/Utilities/Sustainability Sector", "headline": "Gas Malaysia and PETRONAS Gas Study Yan LNG Pipeline Link.", "source": "The Star, 7 Sept 2026", "grade": "Neutral", "summary": "The companies signed a joint study agreement for an onshore lateral pipeline connecting the proposed Yan, Kedah LNG regasification terminal to the Peninsular Gas Utilisation system. The study covers technical, commercial, engineering and land requirements.", "impact": "A positive feasibility outcome and subsequent final investment decision widen Gas Malaysia''s supply flexibility. No investment cost, implementation timetable or final investment decision was disclosed.", "regulatory": "-", "entities": ["gas_malaysia", "petronas"]}, {"section": "Malaysia - 7. Energy/Utilities/Sustainability Sector", "headline": "Utilities Sector Set for Stronger 2H2026 as Malakoff Recovery Stays on Track.", "source": "BIMB Research/The Star, 10 Sept 2026", "grade": "Positive", "summary": "BIMB Research projects 2026 sector core earnings growth of 10.6% yoy. Peak system demand reached 22,014 MW in Aug. Higher Tanjung Bin availability and capacity payments underpin Malakoff''s recovery, and BIMB Research expects a resumption of dividends by year-end.", "impact": "Improved plant availability lifts Malakoff cash generation, while rising electricity demand raises the value of dependable capacity.", "regulatory": "-", "entities": ["malakoff"]}, {"section": "Malaysia - 8. Digital Economy/Technology/Media Sector", "headline": "SK Telecom and Tradewinds Explore Cooperation Opportunities.", "source": "SK Telecom, 10 Sept 2026", "grade": "Neutral", "summary": "SK Telecom CEO Jung Jai-hun and Tradewinds director Syed Danial AlBukhary agreed to explore cooperation at GSMA M360 ASEAN in Kuala Lumpur on 9 Sept. No bilateral project scope, investment or timetable was disclosed.", "impact": "Direct talks give Tradewinds a route to assess technology partnerships, with artificial intelligence (AI) infrastructure and cybersecurity worth evaluating for Malakoff, MMC Ports and Bank Muamalat.", "regulatory": "-", "entities": ["tradewinds", "malakoff", "ptp", "bank_muamalat"]}, {"section": "Malaysia - 8. Digital Economy/Technology/Media Sector", "headline": "Firmus Signs Multi-Year OpenAI Agreement for Malaysian Data-Centre Capacity.", "source": "Reuters, 8 Sept 2026", "grade": "Neutral", "summary": "Nvidia-backed Firmus signed a multi-year agreement to supply OpenAI with computing capacity from two Malaysian data centres. Site locations, capacity and contract value were not disclosed.", "impact": "The anchor customer adds to Malaysia''s power and industrial-land pipeline, and competing Johor sites raise the reference point for tenant quality at TBIP and SAC. No link to TBIP or SAC was disclosed.", "regulatory": "-", "entities": ["tbip", "sac"]}, {"section": "Malaysia - 8. Digital Economy/Technology/Media Sector", "headline": "Pekat and TRC Secure RM 207.16 mn of Data-Centre Works.", "source": "The Star, 8-9 Sept 2026", "grade": "Neutral", "summary": "Pekat secured RM 57.18 mn of Johor Bahru earthing and lightning-protection works, due in Feb and Sept 2027. TRC won RM 149.98 mn of underground services from Gamuda Engineering, due on 25 Nov 2026.", "impact": "Electrical and civil awards show the data-centre pipeline moving into execution and set the package size and margin reference for MMC Engineering''s own tendering. Neither award involves an AlBukhary company.", "regulatory": "-", "entities": ["mmc_eng"]}, {"section": "Malaysia - 9. Property Sector", "headline": "Malaysia Records RM 105.12 bn of Property Transactions in 1H2026.", "source": "Bernama/The Star, 10 Sept 2026", "grade": "Mixed", "summary": "The market recorded 187,320 transactions worth RM 105.12 bn. The Malaysia House Price Index rose 0.9% yoy to 234.7 points, with an average price of RM 506,317. Industrial property grew 3.8%, with 3,932 transactions worth RM 14.78 bn. Completed unsold homes totalled 33,094 units worth RM 17.78 bn.", "impact": "Industrial activity favours demand for Glenmarie Properties and MMC Land, while the residential overhang constrains mass-market launches; limited Group impact on the residential leg, watch item.", "regulatory": "-", "entities": ["glenmarie", "mmc_land"]}, {"section": "Malaysia - 10. Aviation Sector", "headline": "No High-Priority Aviation Development Identified.", "source": "Editorial, 7-11 Sept 2026", "grade": "Neutral", "summary": "No high-priority aviation development was identified for 7-11 Sept with a confirmed operating or financial impact on Senai Airport City or Pos Aviation.", "impact": "No read-through this week.", "regulatory": "-", "entities": ["sac", "pos_aviation"]}, {"section": "Malaysia - 11. Financial Services Sector", "headline": "Maybank Completes RM 4.83 bn Acquisition of Remaining Ageas Stake.", "source": "The Star, 11 Sept 2026", "grade": "Neutral", "summary": "Maybank completed its acquisition of Ageas''s remaining 30.95% stake in Maybank Ageas Holdings for RM 4.83 bn and now wholly owns the insurance and takaful business.", "impact": "The transaction shows the scale of capital deployment by large Malaysian banks and gives Bank Muamalat a capital-planning comparison. No change to Bank Muamalat''s own position follows.", "regulatory": "Bank Negara Malaysia (BNM) approval was received on 1 Sept; the acquisition completed on 11 Sept.", "entities": ["bank_muamalat"]}, {"section": "Malaysia - 11. Financial Services Sector", "headline": "Maybank Raises USD 700 mn in Two-Part Bond Sale.", "source": "Reuters/The Star, 10 Sept 2026", "grade": "Neutral", "summary": "Maybank issued USD 300 mn of three-year floating-rate notes at 60 basis points over the Secured Overnight Financing Rate (SOFR) and USD 400 mn of five-year fixed-rate notes at 55 basis points over US Treasuries, with a 5.09% coupon.", "impact": "Maybank''s spreads give a Malaysian bank credit reference for Bank Muamalat''s own issuance planning, although a sukuk differs in structure and credit profile. Pricing is indicative only.", "regulatory": "-", "entities": ["bank_muamalat"]}, {"section": "Malaysia - 11. Financial Services Sector", "headline": "Malaysian Banks Face Higher Second-Half Credit Costs.", "source": "Business Times/Sarawak Tribune, 7 Sept 2026", "grade": "Mixed", "summary": "Research houses cited expect higher credit costs to limit second-half earnings as loan growth moderates and deposit competition keeps margins tight. Business-loan demand is firm, but slower deposit growth raises funding pressure.", "impact": "Higher credit costs and continued deposit competition pressure Bank Muamalat''s second-half earnings, while firm business-loan demand sustains its financing pipeline.", "regulatory": "-", "entities": ["bank_muamalat"]}]',
  '["Strait of Hormuz and oil prices. Monitor tanker traffic, insurance premiums and fuel prices for Malakoff and MMC Ports customers.", "MIDA''s Data Centre Nexus 2026, 14 Sept. Assess policy and investment announcements affecting TBIP, SAC, Malakoff, Gas Malaysia and Bank Muamalat.", "Federal Open Market Committee, 15-16 Sept. Track the rate decision and guidance for USD/MYR, sukuk valuations and Bank Muamalat''s wholesale funding.", "Bank of Japan, 17-18 Sept. Review the rate decision and yen movements affecting DRB-HICOM''s Japanese component costs.", "Malaysia fuel prices, 17 Sept. Track weekly changes in unsubsidised diesel and petrol for Pos Malaysia and MMC Ports haulage costs.", "Malaysian Automotive Association Aug total industry volume. Evaluate publication against Jul''s 73,615 units, the 800,000-unit 2026 forecast and Proton''s record Aug sales of 22,632 units."]',
  'Not carried in this edition.',
  NULL
);
